def longest_pal_len(s):
    """Manacher O(n):插入 # 统一奇偶回文,维护最右回文边界 (c, r),
    用镜像臂长 p[2*c-i] 复用已知信息,避免重复扩展。返回最长回文子串长度。"""
    if not s:
        return 0
    t = "^#" + "#".join(s) + "#$"   # 首尾哨兵 ^ $ 防越界,# 把奇偶回文统一成奇数
    n = len(t)
    p = [0] * n                     # p[i]:以 i 为中心的回文臂长(恰等于原串回文长度)
    c = r = 0                       # c 当前最右回文的中心,r 其右边界(覆盖到的最右下标,闭区间)
    for i in range(1, n - 1):
        if i < r:
            p[i] = min(r - i, p[2 * c - i])   # 对称复用:镜像点 2*c-i
        while t[i + p[i] + 1] == t[i - p[i] - 1]:
            p[i] += 1                          # 哨兵保证比较不越界
        if i + p[i] > r:
            c, r = i, i + p[i]                 # 右边界只增不减 → 均摊 O(n)
    return max(p)

def longest_pal_len(s):
    """中心扩展 O(n²):枚举每个回文中心(单字符中心 + 相邻字符间隙)向两侧扩展。
    作为 Manacher 的对照基线,空间 O(1)。"""
    if not s:
        return 0
    n = len(s)
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1            # 跳出时左右各多走一步,长度需 -1
    best = 0
    for i in range(n):
        best = max(best, expand(i, i), expand(i, i + 1))   # 奇数中心 + 偶数中心
    return best

def longest_pal_len(s):
    """区间 DP O(n²):dp[i][j] 表示 s[i..j] 是否回文,
    dp[i][j] = (s[i]==s[j]) and (j-i<2 or dp[i+1][j-1]),按区间长度从小到大递推。"""
    n = len(s)
    if n == 0:
        return 0
    dp = [[False] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = True            # 单字符天然回文
    best = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and (length == 2 or dp[i + 1][j - 1]):
                dp[i][j] = True
                if length > best:
                    best = length
    return best
